select stf.staff_sign as staffSign, stf.phone, stf.enable_flag as enableFlag, stf.primary_key as staffCode, stfr.primary_key as primaryKey, stfr.unity_no AS unityNo, stfr.sex AS sex, stfr.age AS age, stfr.id_card AS idCard, d.department_sign AS departmentSign, p.post_sign AS postSign, stfr.contract_date AS contractDate, stfr.contract_allotted AS contractAllotted, stfr.address AS address, stfr.birth_date AS birthDate, stfr.remark AS remark, stfr.technical_level AS technicalLevel, stfr.degree AS degree, stfr.major AS major, stfr.speciality AS speciality, stfr.photo AS photo, stfr.graduate_school AS graduateSchool from ${staffTableName} stf left join ${staffRecordTableName} stfr on stf.primary_key = stfr.staff_code left join ${departmentTableName} d on stf.department = d.primary_key left join ${postTableName} p on stf.post = p.primary_key where stf.delete_flag = false and stf.enterprise_code = #{enterpriseCode} and stf.type in (1,3,5,7)
AND stf.phone IN
#{phone}
